public function timeline_grouped(array $r,string $group):array{global $wpdb;$group=in_array($group,['day','week','month'],true)?$group:'day';if($group==='day')return$this->timeline($r);$t=$wpdb->prefix.'wc_order_stats';[$w,$st]=$this->clause();$a=array_merge([$r['start_sql'],$r['end_sql']],$st);$expr=$group==='month'?"DATE_FORMAT(date_created,'%Y-%m-01')":"DATE_SUB(DATE(date_created), INTERVAL WEEKDAY(date_created) DAY)";$q="SELECT {$expr} report_date,COUNT(order_id) orders,COALESCE(SUM(total_sales),0) total_sales,COALESCE(SUM(net_total),0) net_sales FROM {$t} WHERE date_created >= %s AND date_created <= %s {$w} GROUP BY report_date ORDER BY report_date";$rows=$wpdb->get_results($wpdb->prepare($q,$a),ARRAY_A);$out=[];foreach($rows as$x){$o=(int)$x['orders'];$out[]=['date'=>$x['report_date'],'orders'=>$o,'sales'=>(float)$x['total_sales'],'aov'=>$o?(float)$x['net_sales']/$o:0];}return$out;}
