private function channel_order_sets(array $r):array{$sets=[];foreach($this->eligible_orders($r) as$row){$order=wc_get_order((int)$row['order_id']);if(!$order)continue;[$label]=$this->channel_for_order($order);if(!in_array($label,['Instagram','Facebook','TikTok','Google','Organic','Direct','Referral / Other','Legacy / Unattributed'],true))$label='Referral / Other';$sets[$label][(int)$row['order_id']]=true;}return$sets;}
public function returning_timeline_grouped(array $r,string $group):array{global $wpdb;$group=in_array($group,['day','week','month'],true)?$group:'day';if($group==='day')return$this->returning_timeline($r);$t=$wpdb->prefix.'wc_order_stats';[$w,$st]=$this->clause();$a=array_merge([$r['start_sql'],$r['end_sql']],$st);$expr=$group==='month'?"DATE_FORMAT(date_created,'%Y-%m-01')":"DATE_SUB(DATE(date_created), INTERVAL WEEKDAY(date_created) DAY)";$q="SELECT {$expr} report_date,COUNT(DISTINCT CASE WHEN customer_id>0 THEN customer_id END) total_customers,COUNT(DISTINCT CASE WHEN customer_id>0 AND returning_customer=1 THEN customer_id END) returning_customers FROM {$t} WHERE date_created >= %s AND date_created <= %s {$w} GROUP BY report_date ORDER BY report_date";$rows=$wpdb->get_results($wpdb->prepare($q,$a),ARRAY_A);$out=[];foreach($rows as$x){$n=(int)$x['total_customers'];$out[]=['date'=>$x['report_date'],'rate'=>$n?((int)$x['returning_customers']/$n)*100:0];}return$out;}

public function sales_by_channel(array $r):array{$labels=['Instagram','Facebook','TikTok','Google','Organic','Direct','Referral / Other','Legacy / Unattributed'];$out=[];foreach($labels as$label)$out[$label]=['label'=>$label,'bucket'=>$label,'orders'=>0,'sales'=>0.0,'internal'=>[]];foreach($this->eligible_orders($r) as$row){$order_id=(int)$row['order_id'];$order=wc_get_order($order_id);if(!$order)continue;[$label,$internal]=$this->channel_for_order($order);if(!isset($out[$label])){$label='Referral / Other';$internal='other';}$out[$label]['orders']++;$out[$label]['sales']+=(float)$row['total_sales'];$out[$label]['internal'][$internal]=($out[$label]['internal'][$internal]??0)+1;}$rows=[];foreach($out as$v){if($v['orders']||$v['label']==='Legacy / Unattributed')$rows[]=$v;}return$rows;}
private function channel_for_order(WC_Order $order):array{$snapshot=(string)$order->get_meta('_azula_attr_snapshot_version',true);if($snapshot==='')return[$this->missing_snapshot_label($order),$this->missing_snapshot_internal($order)];$source=strtolower(trim((string)$order->get_meta('_azula_attr_source_raw',true)));$medium=strtolower(trim((string)$order->get_meta('_azula_attr_medium_raw',true)));$normalized=strtolower(trim((string)$order->get_meta('_azula_attr_channel_normalized',true)));if(in_array($source,['ig','instagram'],true)&&$medium==='paid')return['Instagram','instagram'];if(in_array($source,['fb','facebook'],true)&&$medium==='paid')return['Facebook','facebook'];/* TikTok intentionally has no guessed identifiers until validated raw evidence exists. */if($source==='google'&&in_array($medium,['cpc','ppc','paidsearch'],true))return['Google','google_paid'];if($normalized==='organic search'||$medium==='organic')return['Organic','organic'];if($normalized==='direct'||($source==='(direct)'&&$medium==='(none)'))return['Direct','direct'];return['Referral / Other','other'];}
private function attribution_activation_ts():int{$raw=defined('AZULA_ANALYTICS_ATTRIBUTION_ACTIVATED_AT')?(string)AZULA_ANALYTICS_ATTRIBUTION_ACTIVATED_AT:'2026-09-27T00:00:00Z';$ts=strtotime($raw);return$ts===false?0:$ts;}
private function missing_snapshot_internal(WC_Order $order):string{$activation=$this->attribution_activation_ts();$created=$order->get_date_created();$ts=$created?$created->getTimestamp():0;return($activation>0&&$ts>=$activation)?'post_activation_unattributed':'legacy_unattributed';}
private function missing_snapshot_label(WC_Order $order):string{return'Legacy / Unattributed';}

private function payment_order_sets(array $r):array{$sets=[];foreach($this->eligible_orders($r)as$row){$o=wc_get_order((int)$row['order_id']);if(!$o)continue;$g=$this->payment_group((string)$o->get_payment_method(),(string)$o->get_payment_method_title());$sets[$g][(int)$row['order_id']]=true;}return$sets;}
public function payment_methods(array $r):array{$groups=['Cash on Delivery'=>[0,0.0],'Card'=>[0,0.0],'Mobile Wallet'=>[0,0.0],'Manual'=>[0,0.0],'Gift Card'=>[0,0.0],'Other'=>[0,0.0]];foreach($this->eligible_orders($r)as$row){$id=(int)$row['order_id'];$o=wc_get_order($id);if(!$o)continue;$g=$this->payment_group((string)$o->get_payment_method(),(string)$o->get_payment_method_title());$groups[$g][0]++;$groups[$g][1]+=(float)$row['total_sales'];}$out=[];foreach($groups as$g=>$v)if($v[0])$out[]=['label'=>$g,'bucket'=>$g,'orders'=>$v[0],'sales'=>$v[1]];usort($out,fn($a,$b)=>$b['sales']<=>$a['sales']);return$out;}
private function payment_group(string $id,string $title):string{$i=strtolower(trim($id));$t=strtolower(trim($title));if($i==='cod'||str_contains($t,'cash on delivery')||$t==='cod')return'Cash on Delivery';if(in_array($i,['paymob-5060618-uig-online-new-uig-egp','paymob-5069181-wallet-uig-egp'],true)||str_contains($t,'mobile wallet')||str_contains($t,'wallet'))return'Mobile Wallet';if($i==='paymob-5060619-migs-online-vpc-egp'||str_contains($t,'debit/credit card')||str_contains($t,'credit card')||str_contains($t,'paymob - card'))return'Card';if(str_contains($i,'gift')||str_contains($t,'gift card'))return'Gift Card';if($i==='manual'||$t==='manual')return'Manual';return'Other';}

private function product_rows(array $r):array{global $wpdb;$s=$wpdb->prefix.'wc_order_stats';$p=$wpdb->prefix.'wc_order_product_lookup';[$w,$st]=$this->clause('s');$a=array_merge([$r['start_sql'],$r['end_sql']],$st);$q="SELECT p.product_id,SUM(p.product_qty) items,SUM(p.product_net_revenue) revenue,COUNT(DISTINCT p.order_id) orders FROM {$p} p INNER JOIN {$s} s ON s.order_id=p.order_id WHERE s.date_created >= %s AND s.date_created <= %s {$w} GROUP BY p.product_id";return$wpdb->get_results($wpdb->prepare($q,$a),ARRAY_A);}
private function classified(array $r,string $kind):array{$c=new Azula_Analytics_Product_Classifier();$out=[];foreach($this->product_rows($r)as$x){$pid=(int)$x['product_id'];$g=$c->{$kind}($pid);if(!isset($out[$g]))$out[$g]=['label'=>$g,'bucket'=>$g,'items'=>0,'sales'=>0.0,'orders'=>0];$out[$g]['items']+=(int)$x['items'];$out[$g]['sales']+=(float)$x['revenue'];}$order_sets=$this->classified_order_sets($r,$kind,$c);foreach($order_sets as$g=>$set){if(isset($out[$g]))$out[$g]['orders']=count($set);}usort($out,fn($a,$b)=>$b['sales']<=>$a['sales']);return$out;}
private function classified_order_sets(array $r,string $kind,?Azula_Analytics_Product_Classifier $c=null):array{global $wpdb;$c=$c?:new Azula_Analytics_Product_Classifier();$s=$wpdb->prefix.'wc_order_stats';$p=$wpdb->prefix.'wc_order_product_lookup';[$w,$st]=$this->clause('s');$a=array_merge([$r['start_sql'],$r['end_sql']],$st);$rows=$wpdb->get_results($wpdb->prepare("SELECT DISTINCT p.order_id,p.product_id FROM {$p} p INNER JOIN {$s} s ON s.order_id=p.order_id WHERE s.date_created >= %s AND s.date_created <= %s {$w}",$a),ARRAY_A);$sets=[];foreach($rows as$x){$g=$c->{$kind}((int)$x['product_id']);$sets[$g][(int)$x['order_id']]=true;}return$sets;}
public function categories(array $r):array{return$this->classified($r,'category');}public function brands(array $r):array{return$this->classified($r,'brand');}public function genders(array $r):array{return$this->classified($r,'gender');}

