/** Exact order-set source for both displayed counts and lazy drill-downs. */
public function order_ids_for_bucket(array $r,string $report,string $bucket):array{$set=[];switch($report){case'channel':$set=$this->channel_order_sets($r)[$bucket]??[];break;case'payment':$set=$this->payment_order_sets($r)[$bucket]??[];break;case'brand':$set=$this->classified_order_sets($r,'brand')[$bucket]??[];break;case'category':$set=$this->classified_order_sets($r,'category')[$bucket]??[];break;case'gender':$set=$this->classified_order_sets($r,'gender')[$bucket]??[];break;case'coupon':$set=$this->coupon_order_sets($r)[$bucket]??[];break;case'product':$set=$this->product_order_set($r,(int)$bucket);break;case'customer_orders':$cid=(int)$bucket;if($cid>0){global $wpdb;$t=$wpdb->prefix.'wc_order_stats';[$w,$st]=$this->clause();$a=array_merge([$r['start_sql'],$r['end_sql'],$cid],$st);$rows=$wpdb->get_col($wpdb->prepare("SELECT order_id FROM {$t} WHERE date_created >= %s AND date_created <= %s AND customer_id=%d {$w} ORDER BY order_id",$a));foreach($rows as$id)$set[(int)$id]=true;}break;case'orders':foreach($this->eligible_orders($r)as$row)$set[(int)$row['order_id']]=true;break;default:return[];}$ids=array_map('intval',array_keys($set));sort($ids,SORT_NUMERIC);return$ids;}

