public function customer_ids_for_returning(array $r,string $bucket):array{global $wpdb;$t=$wpdb->prefix.'wc_order_stats';[$w,$st]=$this->clause();$a=array_merge([$r['start_sql'],$r['end_sql']],$st);$extra=$bucket==='returning'?' AND returning_customer=1':'';if(!in_array($bucket,['returning','all'],true))return[];$rows=$wpdb->get_col($wpdb->prepare("SELECT DISTINCT customer_id FROM {$t} WHERE date_created >= %s AND date_created <= %s {$w} AND customer_id>0{$extra} ORDER BY customer_id",$a));$ids=array_map('intval',$rows);sort($ids,SORT_NUMERIC);return$ids;}
public function customer_details(array $r,array $ids,int $page=1,int $per_page=25):array{global $wpdb;$ids=array_values(array_unique(array_filter(array_map('intval',$ids))));sort($ids,SORT_NUMERIC);$total=count($ids);$page=max(1,$page);$per_page=max(1,min(50,$per_page));$slice=array_slice($ids,($page-1)*$per_page,$per_page);$rows=[];if($slice){$t=$wpdb->prefix.'wc_order_stats';[$w,$st]=$this->clause();foreach($slice as$id){$args=array_merge([$r['start_sql'],$r['end_sql'],$id],$st);$x=$wpdb->get_row($wpdb->prepare("SELECT COUNT(order_id) orders,COALESCE(SUM(total_sales),0) total_spent FROM {$t} WHERE date_created >= %s AND date_created <= %s AND customer_id=%d {$w}",$args),ARRAY_A);$lookup=$wpdb->get_row($wpdb->prepare("SELECT user_id,first_name,last_name,email FROM {$wpdb->prefix}wc_customer_lookup WHERE customer_id=%d",$id),ARRAY_A);$name=trim((string)($lookup['first_name']??'').' '.(string)($lookup['last_name']??''));if($name==='')$name='Customer #'.$id;$user_id=(int)($lookup['user_id']??0);$url=$user_id>0?admin_url('user-edit.php?user_id='.$user_id):'';$rows[]=['id'=>$id,'name'=>$name,'email'=>(string)($lookup['email']??''),'orders'=>(int)($x['orders']??0),'total_spent'=>(float)($x['total_spent']??0),'url'=>$url];}}
return['rows'=>$rows,'total'=>$total,'page'=>$page,'per_page'=>$per_page,'pages'=>max(1,(int)ceil($total/$per_page))];}

public function order_details(array $ids,int $page=1,int $per_page=25):array{$ids=array_values(array_unique(array_filter(array_map('intval',$ids))));rsort($ids,SORT_NUMERIC);$total=count($ids);$page=max(1,$page);$per_page=max(1,min(50,$per_page));$slice=array_slice($ids,($page-1)*$per_page,$per_page);$rows=[];foreach($slice as$id){$o=wc_get_order($id);if(!$o)continue;$date=$o->get_date_created();$customer=trim((string)$o->get_formatted_billing_full_name());if($customer==='')$customer='Guest';$rows[]=['id'=>$id,'number'=>$o->get_order_number(),'customer'=>$customer,'date'=>$date?$date->date_i18n('M j, Y'):'—','status'=>wc_get_order_status_name($o->get_status()),'total'=>(float)$o->get_total(),'url'=>$o->get_edit_order_url()];}return['rows'=>$rows,'total'=>$total,'page'=>$page,'per_page'=>$per_page,'pages'=>max(1,(int)ceil($total/$per_page))];}

/** v0.5.2: Best Sellers uses parent Product ID as canonical identity. Read-only. */
private function best_seller_search_sql(string $search,array &$args):string{global $wpdb;if($search==='')return'';$like='%'.$wpdb->esc_like($search).'%';if(ctype_digit($search)){$args[]=(int)$search;$args[]=$like;return' AND (p.product_id=%d OR pr.post_title LIKE %s)';}$args[]=$like;return' AND pr.post_title LIKE %s';}
private function best_seller_rows(array $r,int $limit,int $offset=0,string $search=''):array{global $wpdb;$s=$wpdb->prefix.'wc_order_stats';$p=$wpdb->prefix.'wc_order_product_lookup';$posts=$wpdb->posts;[$w,$st]=$this->clause('s');$args=[$r['start_sql'],$r['end_sql']];$where=$this->best_seller_search_sql($search,$args);$args=array_merge($args,$st,[max(1,$limit),max(0,$offset)]);$q="SELECT p.product_id,COALESCE(pr.post_title,'') product_title,SUM(p.product_qty) items,COUNT(DISTINCT p.order_id) orders,COALESCE(SUM(p.product_gross_revenue),0) sales FROM {$p} p INNER JOIN {$s} s ON s.order_id=p.order_id LEFT JOIN {$posts} pr ON pr.ID=p.product_id WHERE s.date_created >= %s AND s.date_created <= %s {$where} {$w} GROUP BY p.product_id,pr.post_title ORDER BY items DESC,p.product_id ASC LIMIT %d OFFSET %d";return$wpdb->get_results($wpdb->prepare($q,$args),ARRAY_A);}
private function best_seller_count(array $r,string $search=''):int{global $wpdb;$s=$wpdb->prefix.'wc_order_stats';$p=$wpdb->prefix.'wc_order_product_lookup';$posts=$wpdb->posts;[$w,$st]=$this->clause('s');$args=[$r['start_sql'],$r['end_sql']];$where=$this->best_seller_search_sql($search,$args);$args=array_merge($args,$st);$q="SELECT COUNT(DISTINCT p.product_id) FROM {$p} p INNER JOIN {$s} s ON s.order_id=p.order_id LEFT JOIN {$posts} pr ON pr.ID=p.product_id WHERE s.date_created >= %s AND s.date_created <= %s {$where} {$w}";return(int)$wpdb->get_var($wpdb->prepare($q,$args));}
private function current_stock_for_parent(int $product_id):?float{$product=wc_get_product($product_id);if(!$product)return null;if($product->is_type('variable')){$seen=false;$sum=0.0;foreach($product->get_children() as$vid){$v=wc_get_product((int)$vid);if(!$v||!$v->managing_stock())continue;$q=$v->get_stock_quantity();if($q===null)continue;$seen=true;$sum+=(float)$q;}if($seen)return$sum;if($product->managing_stock()&&$product->get_stock_quantity()!==null)return(float)$product->get_stock_quantity();return null;}if($product->managing_stock()&&$product->get_stock_quantity()!==null)return(float)$product->get_stock_quantity();return null;}
private function current_stock_details(int $product_id):array{$product=wc_get_product($product_id);if(!$product)return['stock'=>null,'sizes'=>[]];if(!$product->is_type('variable'))return['stock'=>$this->current_stock_for_parent($product_id),'sizes'=>[]];$seen=false;$sum=0.0;$sizes=[];foreach($product->get_children() as$vid){$v=wc_get_product((int)$vid);if(!$v||!$v->managing_stock())continue;$q=$v->get_stock_quantity();if($q===null)continue;$seen=true;$q=(float)$q;$sum+=$q;if($q<=0)continue;$raw=trim((string)$v->get_attribute('pa_size'));if($raw==='')$raw=trim((string)$v->get_meta('attribute_pa_size',true));if($raw==='')$raw='Other';$label=strtoupper(str_replace([' ','-'],'',$raw));$label=['2XL'=>'XXL','3XL'=>'XXXL'][$label]??$label;$sizes[$label]=($sizes[$label]??0)+$q;}if($seen){$order=['XXS','XS','S','M','L','XL','XXL','XXXL'];uksort($sizes,static function($a,$b)use($order){$ia=array_search($a,$order,true);$ib=array_search($b,$order,true);$ia=$ia===false?999:$ia;$ib=$ib===false?999:$ib;return$ia===$ib?strnatcasecmp($a,$b):$ia<=>$ib;});return['stock'=>$sum,'sizes'=>$sizes];}return['stock'=>$this->current_stock_for_parent($product_id),'sizes'=>[]];}
private function decorate_best_sellers(array $rows):array{$out=[];foreach($rows as$row){$id=(int)$row['product_id'];$stock=$this->current_stock_details($id);$out[]=['product_id'=>$id,'product'=>(string)($row['product_title']?:('Product #'.$id)),'items'=>(int)$row['items'],'orders'=>(int)$row['orders'],'sales'=>(float)$row['sales'],'stock'=>$stock['stock'],'stock_sizes'=>$stock['sizes'],'url'=>get_edit_post_link($id,'')?:admin_url('post.php?post='.$id.'&action=edit'),'bucket'=>(string)$id];}return$out;}
public function best_sellers(array $r,int $limit=6):array{return$this->decorate_best_sellers($this->best_seller_rows($r,max(1,$limit),0));}
public function best_sellers_page(array $r,int $page=1,int $per_page=25,string $search=''):array{$page=max(1,$page);$per_page=max(1,min(100,$per_page));$total=$this->best_seller_count($r,$search);$rows=$this->best_seller_rows($r,$per_page,($page-1)*$per_page,$search);return['rows'=>$this->decorate_best_sellers($rows),'total'=>$total,'page'=>$page,'per_page'=>$per_page,'pages'=>max(1,(int)ceil($total/$per_page))];}
private function product_order_set(array $r,int $product_id):array{global $wpdb;$s=$wpdb->prefix.'wc_order_stats';$p=$wpdb->prefix.'wc_order_product_lookup';[$w,$st]=$this->clause('s');$a=array_merge([$r['start_sql'],$r['end_sql'],$product_id],$st);$rows=$wpdb->get_col($wpdb->prepare("SELECT DISTINCT p.order_id FROM {$p} p INNER JOIN {$s} s ON s.order_id=p.order_id WHERE s.date_created >= %s AND s.date_created <= %s AND p.product_id=%d {$w} ORDER BY p.order_id",$a));$set=[];foreach($rows as$id)$set[(int)$id]=true;return$set;}

/** v0.5.2: sold clothing sizes from historical order-line metadata. */
public function best_selling_sizes(array $r):array{global $wpdb;$s=$wpdb->prefix.'wc_order_stats';$oi=$wpdb->prefix.'woocommerce_order_items';$im=$wpdb->prefix.'woocommerce_order_itemmeta';[$w,$st]=$this->clause('s');$a=array_merge([$r['start_sql'],$r['end_sql']],$st);$q="SELECT oi.order_item_id,oi.order_id,MAX(CASE WHEN m.meta_key='_product_id' THEN m.meta_value END) product_id,MAX(CASE WHEN m.meta_key='_variation_id' THEN m.meta_value END) variation_id,MAX(CASE WHEN m.meta_key='_qty' THEN m.meta_value END) qty,MAX(CASE WHEN m.meta_key IN ('pa_size','attribute_pa_size') THEN m.meta_value END) size_value FROM {$oi} oi INNER JOIN {$s} s ON s.order_id=oi.order_id INNER JOIN {$im} m ON m.order_item_id=oi.order_item_id WHERE oi.order_item_type='line_item' AND s.date_created >= %s AND s.date_created <= %s {$w} GROUP BY oi.order_item_id,oi.order_id";$rows=$wpdb->get_results($wpdb->prepare($q,$a),ARRAY_A);$missing=[];foreach($rows as$row)if(trim((string)$row['size_value'])===''&&(int)$row['variation_id']>0)$missing[(int)$row['variation_id']]=true;$fallback=[];if($missing){$ids=array_keys($missing);$ph=implode(',',array_fill(0,count($ids),'%d'));$pm=$wpdb->postmeta;$q2="SELECT post_id,meta_value FROM {$pm} WHERE meta_key='attribute_pa_size' AND post_id IN ({$ph})";foreach($wpdb->get_results($wpdb->prepare($q2,$ids),ARRAY_A)as$x)$fallback[(int)$x['post_id']]=(string)$x['meta_value'];}$classifier=new Azula_Analytics_Product_Classifier();$allowed=['Hoodies & Jackets','Leggings','Pants','Tops','Sports Bras','Socks','Shorts','Accessories'];$preferred=['XXS','XS','S','M','L','XL','XXL','XXXL'];$out=[];foreach($rows as$row){$pid=(int)$row['product_id'];$qty=(int)$row['qty'];$raw=trim((string)$row['size_value']);if($raw===''&&(int)$row['variation_id']>0)$raw=trim((string)($fallback[(int)$row['variation_id']]??''));if($pid<1||$qty<=0||$raw==='')continue;$gender=$classifier->gender($pid);if(!in_array($gender,['Women','Men','Unisex'],true))continue;$category=$classifier->category($pid);if(!in_array($category,$allowed,true))continue;$size=strtoupper(str_replace([' ','-'],'',$raw));$aliases=['2XL'=>'XXL','3XL'=>'XXXL'];$size=$aliases[$size]??$size;$key=in_array($size,$preferred,true)?$size:'Other: '.sanitize_text_field($raw);if(!isset($out[$gender][$category]))$out[$gender][$category]=['category'=>$category,'sizes'=>[],'total'=>0];$out[$gender][$category]['sizes'][$key]=($out[$gender][$category]['sizes'][$key]??0)+$qty;$out[$gender][$category]['total']+=$qty;}foreach($out as&$sections)uasort($sections,fn($a,$b)=>$b['total']<=>$a['total']);unset($sections);return['sections'=>$out,'preferred'=>$preferred];}

/** v0.5.3 read-only drill-down helpers. Existing classifiers/calculations remain unchanged. */
private function sold_line_rows(array $r):array{global $wpdb;$s=$wpdb->prefix.'wc_order_stats';$oi=$wpdb->prefix.'woocommerce_order_items';$im=$wpdb->prefix.'woocommerce_order_itemmeta';[$w,$st]=$this->clause('s');$a=array_merge([$r['start_sql'],$r['end_sql']],$st);$q="SELECT oi.order_item_id,oi.order_id,MAX(CASE WHEN m.meta_key='_product_id' THEN m.meta_value END) product_id,MAX(CASE WHEN m.meta_key='_variation_id' THEN m.meta_value END) variation_id,MAX(CASE WHEN m.meta_key='_qty' THEN m.meta_value END) qty,MAX(CASE WHEN m.meta_key IN ('pa_size','attribute_pa_size') THEN m.meta_value END) size_value FROM {$oi} oi INNER JOIN {$s} s ON s.order_id=oi.order_id INNER JOIN {$im} m ON m.order_item_id=oi.order_item_id WHERE oi.order_item_type='line_item' AND s.date_created >= %s AND s.date_created <= %s {$w} GROUP BY oi.order_item_id,oi.order_id";return$wpdb->get_results($wpdb->prepare($q,$a),ARRAY_A);}
private function normalized_sold_size(array $row,array &$fallback):string{$raw=trim((string)($row['size_value']??''));$vid=(int)($row['variation_id']??0);if($raw===''&&$vid>0){if(!array_key_exists($vid,$fallback)){$v=wc_get_product($vid);$fallback[$vid]=$v?trim((string)$v->get_attribute('pa_size')):'';}$raw=$fallback[$vid];}if($raw==='')return'';$size=strtoupper(str_replace([' ','-'],'',$raw));return['2XL'=>'XXL','3XL'=>'XXXL'][$size]??$size;}
public function size_contributors(array $r,string $gender,string $category,string $size):array{$c=new Azula_Analytics_Product_Classifier();$allowed=['Hoodies & Jackets','Leggings','Pants','Tops','Sports Bras','Socks','Shorts','Accessories'];$fallback=[];$out=[];foreach($this->sold_line_rows($r)as$row){$pid=(int)$row['product_id'];$vid=(int)$row['variation_id'];$qty=(int)$row['qty'];if($pid<1||$qty<=0||$c->gender($pid)!==$gender||$c->category($pid)!==$category||!in_array($category,$allowed,true))continue;$sz=$this->normalized_sold_size($row,$fallback);$target=str_starts_with($size,'Other: ')?strtoupper(str_replace([' ','-'],'',substr($size,7))):$size;if($sz!==$target)continue;$key=$pid.':'.$vid;if(!isset($out[$key])){$v=$vid?wc_get_product($vid):null;$out[$key]=['product_id'=>$pid,'variation_id'=>$vid,'product'=>get_the_title($pid)?:('Product #'.$pid),'sku'=>$v?(string)$v->get_sku():'','items'=>0,'orders'=>[],'url'=>get_edit_post_link($pid,'')?:admin_url('post.php?post='.$pid.'&action=edit')];}$out[$key]['items']+=$qty;$out[$key]['orders'][(int)$row['order_id']]=true;}foreach($out as&$x){$x['order_ids']=array_map('intval',array_keys($x['orders']));$x['orders']=count($x['order_ids']);}unset($x);usort($out,fn($a,$b)=>$b['items']<=>$a['items']?:$a['product_id']<=>$b['product_id']);return$out;}
private function special_brand_category_label(int $pid,Azula_Analytics_Product_Classifier $c):string{foreach([327=>'Alo Men',328=>'Alo Women',306=>'Gymshark Men',312=>'Gymshark Women']as$id=>$label)if(has_term($id,'product_cat',$pid))return$label;$brand=$c->brand($pid);if(in_array(strtolower($brand),['alo','alo yoga','gymshark'],true))return'';return$brand;}
public function brand_category_performance(array $r):array{$c=new Azula_Analytics_Product_Classifier();$allowed=['Hoodies & Jackets','Leggings','Pants','Tops','Sports Bras','Socks','Shorts','Accessories'];$out=[];foreach($this->product_rows($r)as$row){$pid=(int)$row['product_id'];$qty=(int)$row['items'];if($qty<=0)continue;$brand=$this->special_brand_category_label($pid,$c);$cat=$c->category($pid);if($brand===''||!in_array($cat,$allowed,true))continue;if(!isset($out[$brand]))$out[$brand]=['brand'=>$brand,'total'=>0,'categories'=>[]];$out[$brand]['total']+=$qty;$out[$brand]['categories'][$cat]=($out[$brand]['categories'][$cat]??0)+$qty;}foreach($out as&$b)arsort($b['categories'],SORT_NUMERIC);unset($b);usort($out,fn($a,$b)=>$b['total']<=>$a['total']?:strnatcasecmp($a['brand'],$b['brand']));return$out;}
public function brand_category_contributors(array $r,string $brand,string $category):array{$c=new Azula_Analytics_Product_Classifier();$out=[];foreach($this->sold_line_rows($r)as$row){$pid=(int)$row['product_id'];$qty=(int)$row['qty'];if($pid<1||$qty<=0||$this->special_brand_category_label($pid,$c)!==$brand||$c->category($pid)!==$category)continue;if(!isset($out[$pid]))$out[$pid]=['product_id'=>$pid,'product'=>get_the_title($pid)?:('Product #'.$pid),'items'=>0,'orders'=>[],'url'=>get_edit_post_link($pid,'')?:admin_url('post.php?post='.$pid.'&action=edit')];$out[$pid]['items']+=$qty;$out[$pid]['orders'][(int)$row['order_id']]=true;}foreach($out as&$x){$x['order_ids']=array_map('intval',array_keys($x['orders']));$x['orders']=count($x['order_ids']);}unset($x);usort($out,fn($a,$b)=>$b['items']<=>$a['items']?:$a['product_id']<=>$b['product_id']);return$out;}
public function contributor_order_ids(array $r,string $kind,string $key):array{$parts=explode('|',$key);$rows=[];if($kind==='size'&&count($parts)>=5){[$gender,$cat,$size,$pid,$vid]=$parts;$rows=$this->size_contributors($r,$gender,$cat,$size);foreach($rows as$x)if((int)$x['product_id']===(int)$pid&&(int)$x['variation_id']===(int)$vid)return$x['order_ids'];}if($kind==='brandcat'&&count($parts)>=3){[$brand,$cat,$pid]=$parts;$rows=$this->brand_category_contributors($r,$brand,$cat);foreach($rows as$x)if((int)$x['product_id']===(int)$pid)return$x['order_ids'];}return[];}

